<?php declare(strict_types=1);
$locationMessages=$managerLanguageMessages??[];
$locationText=static fn(string $source,array $values=[]):string=>\Kulturhus\Native\Language\InventoryLocationMessages::text($source,$locationMessages,$values);
$locationState=$inventoryLocationState??\Kulturhus\Verein\Web\InventoryLocationForm::state($db,(string)$_SESSION['actor'],$_POST,$_GET);
$edit=$locationState['location'];$locationRequested=input($_POST,'action')==='inventory-location';
$locationListRoute=['view'=>'inventory','tab'=>'locations'];$locationNew=($_GET['new_location']??null)==='1';
$locationRecovery=$edit?($locationListRoute+['location'=>$edit['id']]):($locationNew?($locationListRoute+['new_location'=>'1']):$locationListRoute);
if(!$edit&&$locationNew&&is_string($locationState['key']))$locationRecovery['location_request']=$locationState['key'];
?>
<link rel="stylesheet" href="inventory-locations.css?v=1">
<div class="iv-locations">
<?php if($locationState['original']!==null): ?>
<section class="card iv-location-original" data-location-original><h2><?= e($locationText('Lagerortangaben')) ?></h2><p><?= e($locationText('Die vollständigen ursprünglichen Angaben bleiben zur Prüfung sichtbar. Den tatsächlich geöffneten Lagerort und seinen aktuellen Speicherstand neu prüfen, bevor du erneut speicherst.')) ?></p><pre><?= e(json_encode($locationState['original'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR)) ?></pre><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url($locationRecovery)) ?>"><?= e($locationText($edit?'Gespeicherten Lagerort neu prüfen':($locationNew?'Neue Lagerortanlage neu prüfen':'Lagerortliste öffnen'))) ?></a></section>
<?php endif ?>
<?php if($locationState['saved']!==null): ?>
<section class="card" data-location-saved><h2><?= e($locationText('Dieser Lagerort wurde bereits angelegt.')) ?></h2><p><?= e($locationText('Die ursprüngliche Anlage wird nicht nochmals ausgeführt. Den vorhandenen Lagerort öffnen oder bewusst einen neuen Anlagevorgang beginnen.')) ?></p><p><a class="btn btn-solid theme-primary button" href="<?= e(url($locationListRoute+['location'=>$locationState['saved']['id']])) ?>"><?= e($locationText('Vorhandenen Lagerort öffnen')) ?></a></p><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url($locationListRoute+['new_location'=>'1'])) ?>"><?= e($locationText('Neuen Lagerortvorgang beginnen')) ?></a></section>
<?php endif ?>
<?php if($ivWrite&&!$locationState['blocked']&&($edit||$locationNew)):
 $d=$edit??['name'=>'','holder_id'=>'','building'=>'','room'=>'','shelf'=>'','active'=>'1','notes'=>''];
 if($locationRequested)$d=array_replace($d,$_POST['data']);
 $locationKey=$locationRequested?$_POST['request_key']:($locationState['key']??bin2hex(random_bytes(16)));
 $locationVersion=$locationRequested?$_POST['version']:(string)($edit['version']??0);
 $locationAction=$edit?($locationListRoute+['location'=>$edit['id']]):($locationListRoute+['new_location'=>'1','location_request'=>$locationKey]);
?>
<form method="post" class="card" id="inventory-location-form" action="<?= e(url($locationAction)) ?>"><?= csrf().hidden('action','inventory-location').hidden('target',$edit['id']??'').hidden('version',$locationVersion).hidden('request_key',$locationKey) ?><h2><?= e($locationText($edit?'Lagerort bearbeiten':'Lagerort anlegen')) ?></h2><div class="iv-form-grid">
<label><?= e($locationText('Name des Lagerorts')) ?> <span class="required">*</span><input class="form-control" name="data[name]" required maxlength="120" value="<?= e($d['name']) ?>"></label>
<label><?= e($locationText('Aufbewahrendes Mitglied / Kontakt')) ?><select class="form-control" name="data[holder_id]" data-select-native><?php if(($d['holder_id']??'')!==''&&!array_key_exists((string)$d['holder_id'],$personOptions)): ?><option value="<?= e((string)$d['holder_id']) ?>" selected><?= e($locationText('Ausgewählte Person nicht mehr verfügbar – bitte neu auswählen')) ?></option><?php endif ?><?php foreach($personOptions as $id=>$label): ?><option value="<?= e((string)$id) ?>" <?= (string)$id===(string)($d['holder_id']??'')?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select></label>
<?php foreach(['building'=>'Gebäude / Veranstaltungsort','room'=>'Raum','shelf'=>'Regal / Fach']as$field=>$label): ?><label><?= e($locationText($label)) ?><input class="form-control" name="data[<?= e($field) ?>]" maxlength="120" value="<?= e($d[$field]??'') ?>"></label><?php endforeach ?>
<label><?= e($locationText('Status')) ?><select class="form-control" name="data[active]"><option value="1" <?= (string)$d['active']==='1'?'selected':'' ?>><?= e($locationText('Aktiv')) ?></option><option value="0" <?= (string)$d['active']==='0'?'selected':'' ?>><?= e($locationText('Archiviert')) ?></option></select></label>
<label class="iv-location-wide"><?= e($locationText('Hinweise')) ?><textarea class="form-control" name="data[notes]" maxlength="2000" rows="4"><?= e($d['notes']) ?></textarea></label>
</div><p class="muted"><?= e($locationText('Auch „bei …“ ist ein Lagerort. Eine Privatadresse ist keine Pflicht. Dauerhafte Aufbewahrung erzeugt keine Ausleihe.')) ?></p><div class="actions"><button class="btn btn-solid theme-primary"><?= e($locationText('Lagerort speichern')) ?></button><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url($locationListRoute)) ?>"><?= e($locationText('Abbrechen / zu den Lagerorten')) ?></a></div></form>
<?php elseif($edit): ?>
<section class="card" data-location-read><h2><?= e($locationText('Gespeicherter Lagerort')) ?></h2><dl class="data-list"><?php foreach(['name'=>'Name des Lagerorts','building'=>'Gebäude / Veranstaltungsort','room'=>'Raum','shelf'=>'Regal / Fach','notes'=>'Hinweise']as$field=>$label): ?><dt><?= e($locationText($label)) ?></dt><dd><?= e((string)($edit[$field]??'')) ?></dd><?php endforeach ?><dt><?= e($locationText('Aufbewahrendes Mitglied / Kontakt')) ?></dt><dd><?= e($personOptions[$edit['holder_id']??'']??$locationText('Keine Zuordnung')) ?></dd><dt><?= e($locationText('Status')) ?></dt><dd><?= e($locationText($edit['active']?'Aktiv':'Archiviert')) ?></dd></dl><?php if(!$ivWrite): ?><p class="muted"><?= e($locationText('Du hast hier Leserechte. Änderungen übernimmt die Inventarverwaltung.')) ?></p><?php endif ?></section>
<?php endif ?>
<section class="card"><h2><?= e($locationText('Lagerorte & Aufbewahrung')) ?></h2><div class="iv-location-grid" data-simple-list="<?= e($locationText('Lagerorte suchen (Name, Person, Status)')) ?>" data-simple-list-rows="a.iv-location" data-simple-list-size="12"><?php foreach($locations as $l): ?><a class="iv-location" href="<?= e(url($locationListRoute+['location'=>$l['id']])) ?>"><h3><?= e($l['name']) ?></h3><p><?= e($personOptions[$l['holder_id']]??$locationText('Vereinslager · ohne Personenzuordnung')) ?></p><small><?= e(implode(' · ',array_filter([$l['building'],$l['room'],$l['shelf']],static fn($value)=>$value!==null&&$value!==''))) ?></small><span class="status <?= $l['active']?'aktiv':'' ?>"><?= e($locationText($l['active']?'Aktiv':'Archiviert')) ?></span></a><?php endforeach;if(!$locations): ?><p class="muted"><?= e($locationText('Lege zuerst euren Vereinsraum oder einen privaten Aufbewahrungsort an.')) ?></p><?php endif ?></div></section>
<?php if($edit): ?><section class="card"><div class="section-heading"><h2><?= e($locationText('Aktuell in {name}',['name'=>$edit['name']])) ?></h2><?php ivExport('stock',['location'=>$edit['id']],$locationText); ?></div><?php ivWhereTable($inventory->whereabouts(['location'=>$edit['id']]),$ivActorNames,true,$locationText); ?></section><?php endif ?>
</div>
